import { Group, Mesh, PlaneGeometry, BoxGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {any} textContent
 * @property {any} intent
 * @property {any} typography
 * @property {any} colors
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} tier
 */

/**
 * Create a node representing an editorial oversized type layout.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE;

  // Root container – position/rotation/scale are applied by the adapter.
  const root = new Group();

  // -------------------------------------------------------------------------
  // Backdrop Plane with vertical gradient
  // -------------------------------------------------------------------------
  const backdropGeom = new PlaneGeometry(7, 5.5);
  const c0 = vec3(11 / 255, 11 / 255, 16 / 255); // #0b0b10
  const c1 = vec3(20 / 255, 26 / 255, 26 / 255); // #14141a
  const gradientNode = mix(c0, c1, uv().y);
  const backdropMat = new MeshBasicNodeMaterial({ color: gradientNode });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, 0);
  root.add(backdrop);

  // -------------------------------------------------------------------------
  // Underline Rule (emissive strip)
  // -------------------------------------------------------------------------
  const underlineGeom = new PlaneGeometry(2.2, 0.05);
  const underlineMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    emissive: 0xff2a38,
    emissiveIntensity: 1.2,
    metalness: 0,
    roughness: 1,
  });
  const underline = new Mesh(underlineGeom, underlineMat);
  // Left‑align at x = -3.1
  underline.position.set(-3.1 + 2.2 / 2, -0.15, 0.01);
  underline.scale.set(0, 1, 1); // start collapsed, will scaleX later
  root.add(underline);

  // -------------------------------------------------------------------------
  // Text Items
  // -------------------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Helper to fetch typographic options from config.typography if present
  const getTypoOpts = (role) => {
    const spec = config.typography?.[role] ?? {};
    const opts = {
      fontSize: spec.fontSize ?? 20,
      color: spec.color ?? '#e8ecf2',
      align: 'left',
    };
    if (typeof spec.letterSpacing === 'number') {
      // spec.letterSpacing is in em, convert to pixels using fontSize
      opts.letterSpacingPx = spec.letterSpacing * opts.fontSize;
    }
    return opts;
  };

  // Mapping of item index to role and Y position
  const roleMap = [
    { role: 'kicker', y: 1.7 },
    { role: 'hero', y: 0.9 },
    { role: 'hero', y: 0.25 },
    { role: 'body', y: -0.8 },
    { role: 'caption', y: -1.9 },
  ];

  /** @type {{obj: THREE.Object3D, mesh: THREE.Mesh, targetY:number}[]} */
  const animatedBlocks = [];

  items.forEach((item, idx) => {
    if (!roleMap[idx]) return;
    const { role, y } = roleMap[idx];
    const txt = typeof item === 'string' ? item : item.text ?? '';

    // Common options
    const opts = getTypoOpts(role);
    opts.fontSize = role === 'hero' ? 124 : role === 'kicker' ? 18 : role === 'body' ? 26 : 18;

    // Hero has special shadow duplicate
    if (role === 'hero') {
      // Shadow duplicate (ink color, slightly behind)
      const shadowOpts = { ...opts };
      shadowOpts.color = '#16161d';
      const shadow = ctx.fontAtlas.createText(txt, shadowOpts);
      shadow.position.set(-3.1, y, -0.02);
      root.add(shadow);
    }

    // Main text
    const textObj = ctx.fontAtlas.createText(txt, opts);
    textObj.position.set(-3.1, y, 0);
    // Ensure opacity starts at 0 for animation
    let primaryMesh = null;
    textObj.traverse((c) => {
      if (c.isMesh) {
        primaryMesh = c;
        c.material.transparent = true;
        c.material.opacity = 0;
      }
    });
    root.add(textObj);
    if (primaryMesh) {
      animatedBlocks.push({ obj: textObj, mesh: primaryMesh, targetY: y });
    }
  });

  // -------------------------------------------------------------------------
  // Entrance Animation (rise-in with stagger)
  // -------------------------------------------------------------------------
  const timeline = gsap.timeline({ paused: true });
  animatedBlocks.forEach((block, i) => {
    const { obj, mesh, targetY } = block;
    // start offset
    obj.position.y = targetY + 0.4;
    // animate position and opacity
    timeline.to(
      obj.position,
      { y: targetY, duration: 0.7, ease: 'power3.out' },
      i * 0.08
    );
    timeline.to(
      mesh.material,
      { opacity: 1, duration: 0.7, ease: 'power3.out' },
      i * 0.08
    );
  });

  // Underline scaleX animation after hero lands (approx after last hero block)
  const heroEndTime = 0.7 + (2 - 1) * 0.08 + 0.7; // rough estimate
  timeline.to(
    underline.scale,
    {
      x: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    heroEndTime + 0.1
  );

  timeline.play();

  // -------------------------------------------------------------------------
  // Cleanup
  // -------------------------------------------------------------------------
  const cleanup = () => {
    timeline.kill();
    // Dispose geometries and materials
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
  };

  root.userData.cleanup = cleanup;
  root.userData.handlers = {}; // no interactive handlers for this node

  return root;
}
